const fs = require('fs');
const { Scene } = require('./dist/aspose/threed');
const { Mesh } = require('./dist/aspose/threed/entities');
const { Vector4 } = require('./dist/aspose/threed/utilities');

function triangle() {
  const mesh = new Mesh('tri');
  mesh.controlPoints = [new Vector4(10, 20, 30, 1), new Vector4(11, 20, 30, 1), new Vector4(10, 21, 30, 1)];
  mesh.createPolygon(0, 1, 2);
  return mesh;
}

fs.writeFileSync('model.obj', '# exported by a tool\no Tri\nv 0 0 0\nv 1 0 0\nv 0 1 0\nf 1 2 3\n');

const scene = new Scene();
scene.open('model.obj');
const node = scene.rootNode.childNodes[0];
console.log(node.name, 'control points:', node.entity.controlPoints.length, 'polygons:', node.entity.polygonCount);

