const fs = require('fs');
const { Scene } = require('./dist/aspose/threed');
const { Mesh } = require('./dist/aspose/threed/entities');
const { Vector4 } = require('./dist/aspose/threed/utilities');

function triangle() {
  const mesh = new Mesh('tri');
  mesh.controlPoints = [new Vector4(10, 20, 30, 1), new Vector4(11, 20, 30, 1), new Vector4(10, 21, 30, 1)];
  mesh.createPolygon(0, 1, 2);
  return mesh;
}

const { FbxFormat, FbxExporter, FbxSaveOptions } = require('./dist/aspose/threed/formats/fbx');

const scene = new Scene();
scene.rootNode.entity = triangle();

// 1. Save by file extension
scene.save('out.fbx');
console.log(fs.readFileSync('out.fbx', 'utf8').split('\n').slice(0, 3));

// 2. Save with the FBX format object
try { scene.save('out2.fbx', FbxFormat.getInstance()); } catch (e) { console.log(e.message); }

// 3. Open an FBX file (written here with the library's own FbxExporter)
let text = '';
new FbxExporter().export(scene, { write(d) { text += d; } }, new FbxSaveOptions());
fs.writeFileSync('real.fbx', text);
const loaded = new Scene();
loaded.open('real.fbx');
const mesh = loaded.rootNode.childNodes[0].entity;
console.log(mesh.constructor.name, 'control points:', mesh.controlPoints.length);

